const input = $input.first().json;

// Очищення зайвих лапок
function c(val) {
  if (val === null || val === undefined) return val;
  if (typeof val !== 'string') return val;
  return val.replace(/^"(.*)"$/s, '$1');
}

const rawText = input.output || input.text || input.response || '';

const clean = rawText
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(clean);
} catch (e) {
  parsed = { rationale: 'Потребує негайної уваги ментора.' };
}

const prev = $('Prepare Strategy Input').first().json;

return [{
  json: {
    ...prev,

    // Математично обрані — очищаємо лапки
    recommended_action:        c(prev.recommended_action)        || 'no_action',
    secondary_action:          c(prev.secondary_action)          || null,
    priority:                  c(prev.priority)                  || 'low',
    timing:                    c(prev.timing)                    || 'monitor',
    expected_lift_qualitative: c(prev.expected_lift_qualitative) || 'low',

    // Claude пояснює
    rationale: c(parsed.rationale) || 'Потребує уваги.',
  }
}];

const input = $input.first().json;
const data  = input.body || input;

// Очищення зайвих лапок
function c(val) {
  if (typeof val !== 'string') return val;
  return val.replace(/^"(.*)"$/s, '$1');
}

const computed         = data.computed_signals || {};
const observer         = data.observer_result  || {};
const hwSum            = data.hw_summary       || {};
const riskLevelCalc    = c(data.risk_level_calculated || data.risk_level || 'low');
const activeStageNames = data.active_stage_names || [];
const dropIntent       = observer.has_explicit_dropout_intent || false;
const redZone          = data.red_zone    || false;
const missedHw         = computed.missed_homework_count || 0;
const avgGrade         = parseFloat(c(String(hwSum.avg_grade || '100')));
const state            = c(data.student_state || 'on_track');
const timingShift      = computed.submission_timing_shift || false;
const urgency          = c(data.urgency_calculated || data.urgency || 'monitor');

console.log('Calculate Strategy:');
console.log('  riskLevelCalc:', riskLevelCalc);
console.log('  activeStageNames:', activeStageNames);
console.log('  dropIntent:', dropIntent);
console.log('  timingShift:', timingShift);
console.log('  missedHw:', missedHw);
console.log('  urgency:', urgency);

// ── ЛОГІКА ВИБОРУ ДІЇ ────────────────────────────────────────
let recommendedAction = 'no_action';
let secondaryAction   = null;
let priority          = 'low';
let timing            = 'monitor';

// ЧЕРВОНА ЗОНА або етап 7
if (redZone || activeStageNames.includes('no_mentor_response')) {
  recommendedAction = 'mentor_call';
  secondaryAction   = 'escalation_to_manager';
  priority          = 'critical';
  timing            = 'today';
}
// Етап 6 або явний намір залишити
else if (activeStageNames.includes('negative_messages') || dropIntent) {
  recommendedAction = 'mentor_call';
  // ВИПРАВЛЕННЯ: додаємо escalation якщо dropout_intent = true
  secondaryAction   = dropIntent ? 'escalation_to_manager' : null;
  priority          = 'high';
  timing            = 'today';
}
// Етап 5 — login_gap
else if (activeStageNames.includes('login_gap')) {
  recommendedAction = 'mentor_call';
  secondaryAction   = null;
  priority          = 'high';
  timing            = 'today';
}
// Етап 4 — missed_homework
else if (missedHw >= 2 || activeStageNames.includes('missed_homework')) {
  recommendedAction = 'mentor_call';
  secondaryAction   = null;
  priority          = 'medium';
  timing            = 'this_week';
}
// Низькі оцінки — матеріал
else if (avgGrade < 65 && missedHw === 0) {
  recommendedAction = 'additional_material';
  secondaryAction   = null;
  priority          = 'medium';
  timing            = 'this_week';
}
// Етап 1-3 або submission_timing_shift
else if (
  activeStageNames.includes('late_homework')        ||
  activeStageNames.includes('stopped_questions')    ||
  activeStageNames.includes('missed_live_sessions') ||
  timingShift === true
) {
  recommendedAction = 'personal_message';
  secondaryAction   = null;
  priority          = 'medium';
  timing            = 'this_week';
}
// Silent but OK або low без сигналів
else if (state === 'silent_but_ok' || riskLevelCalc === 'low') {
  recommendedAction = 'no_action';
  secondaryAction   = null;
  priority          = 'low';
  timing            = 'monitor';
}

// ── EXPECTED LIFT ─────────────────────────────────────────────
const liftMap = {
  mentor_call:           'high',
  personal_message:      'medium',
  additional_material:   'medium',
  freeze_course:         'medium',
  next_cohort:           'low',
  escalation_to_manager: 'high',
  no_action:             'low',
};

return [{
  json: {
    ...data,
    recommended_action:        recommendedAction,
    secondary_action:          secondaryAction,
    priority,
    timing,
    expected_lift_qualitative: liftMap[recommendedAction] || 'low',
  }
}];

const input = $input.first().json;
const data     = input.body || input;
const student  = data.student          || {};
const observer = data.observer_result  || {};
const computed = data.computed_signals || {};

const promptText =
  'Поясни чому обрана ця стратегія для студента.\n\n' +

  'СТУДЕНТ: ' + (student.name || '?') + '\n\n' +

  'МАТЕМАТИЧНО ОБРАНА СТРАТЕГІЯ:\n' +
  '- recommended_action: ' + data.recommended_action + '\n' +
  '- secondary_action: ' + (data.secondary_action || 'немає') + '\n' +
  '- priority: ' + data.priority + '\n' +
  '- timing: ' + data.timing + '\n\n' +

  'КОНТЕКСТ РИЗИКУ:\n' +
  '- risk_score: ' + (data.risk_score_calculated || 0) + '\n' +
  '- risk_level: ' + (data.risk_level_calculated || 'low') + '\n' +
  '- student_state: ' + (data.student_state || 'unknown') + '\n' +
  '- urgency: ' + (data.urgency_calculated || 'monitor') + '\n' +
  '- days_to_dropout: ' + (data.days_to_dropout || 'невідомо') + '\n' +
  '- red_zone: ' + (data.red_zone || false) + '\n' +
  '- has_explicit_dropout_intent: ' + (observer.has_explicit_dropout_intent || false) + '\n' +
  '- missed_homework: ' + (computed.missed_homework_count || 0) + '\n\n' +

  'PRIMARY DRIVERS:\n' +
  (data.primary_drivers || []).map(d => '- ' + d).join('\n') + '\n\n' +

  'Поверни ТІЛЬКИ валідний JSON:\n' +
  '{\n' +
  '  "rationale": "<1-2 речення чому саме ця дія потрібна зараз — для ментора>"\n' +
  '}';

return [{
  json: {
    ...data,
    prompt_text: promptText,
  }
}];;
